  const unavailable = { id: 'unavailable', title: 'Lesson not available yet', summary: 'A focused concept lesson has not been added for this question yet.', sections: [], reflect: '', sources: [] };
  function getForItem(item) { return lessons[questionConcepts[item && item.id]] || null; }
  function getForItems(items) {
    const seen = new Set();
    return items.reduce((result, item) => {
      const lesson = getForItem(item) || unavailable;
      if (!seen.has(lesson.id)) { seen.add(lesson.id); result.push(lesson); }
      return result;
    }, []);
  }
  global.NursePathPnleConcepts = { lessons, getForItem, getForItems };
